use polars_core::chunked_array::cast::CastOptions;

use super::*;

pub(super) struct SimpleProjectionAndCollapse {


    processed: BTreeSet<Node>,
    eager: bool,
}

impl SimpleProjectionAndCollapse {
    pub(super) fn new(eager: bool) -> Self {
        Self {
            processed: Default::default(),
            eager,
        }
    }
}

impl OptimizationRule for SimpleProjectionAndCollapse {
    fn optimize_plan(
        &mut self,
        lp_arena: &mut Arena<IR>,
        expr_arena: &mut Arena<AExpr>,
        node: Node,
    ) -> PolarsResult<Option<IR>> {
        use IR::*;
        let lp = lp_arena.get(node);

        match lp {
            Select {
                input,
                expr,
                schema,
                ..
            } => {
                if !self.processed.contains(&node) {

                    if !expr.iter().all(|e| e.plain_column(expr_arena).is_some()) {
                        self.processed.insert(node);
                        return Ok(literal_select_to_scan(expr, schema, expr_arena));
                    }

                    let exprs = expr
                        .iter()
                        .map(|e| e.output_name().clone())
                        .collect::<Vec<_>>();
                    let Some(alp) = IRBuilder::new(*input, expr_arena, lp_arena)
                        .project_simple(exprs.iter().cloned())
                        .ok()
                    else {
                        return Ok(None);
                    };
                    let alp = alp.build();

                    Ok(Some(alp))
                } else {
                    self.processed.insert(node);
                    Ok(None)
                }
            },
            SimpleProjection { columns, input } if !self.eager => {
                match lp_arena.get(*input) {

                    SimpleProjection {
                        input: prev_input, ..
                    } => Ok(Some(SimpleProjection {
                        input: *prev_input,
                        columns: columns.clone(),
                    })),


                    cache_lp @ Cache { .. } if self.processed.contains(&node) => {
                        let cache_schema = cache_lp.schema(lp_arena);
                        if cache_schema.len() == columns.len()
                            && cache_schema.iter_names().zip(columns.iter_names()).all(
                                |(left_name, right_name)| left_name.as_str() == right_name.as_str(),
                            )
                        {
                            Ok(Some(cache_lp.clone()))
                        } else {
                            Ok(None)
                        }
                    },

                    other => {
                        let input_schema = other.schema(lp_arena);

                        if *input_schema.as_ref() == *columns {
                            Ok(Some(other.clone()))
                        } else {
                            self.processed.insert(node);
                            Ok(None)
                        }
                    },
                }
            },

            Cache { input, .. } if !self.eager => {
                if let Cache {
                    input: prev_input,
                    id,
                } = lp_arena.get(*input)
                {
                    Ok(Some(Cache {
                        input: *prev_input,
                        id: *id,
                    }))
                } else {
                    Ok(None)
                }
            },
            _ => Ok(None),
        }
    }
}


fn literal_select_to_scan(
    expr: &[ExprIR],
    schema: &SchemaRef,
    expr_arena: &Arena<AExpr>,
) -> Option<IR> {
    let columns = expr
        .iter()
        .zip(schema.iter())
        .map(|(e, (name, dtype))| {
            let scalar = match expr_arena.get(e.node()) {
                AExpr::Literal(LiteralValue::Scalar(sc)) => sc.clone(),
                AExpr::Literal(LiteralValue::Dyn(d)) => d
                    .clone()
                    .try_materialize_to_dtype(dtype, CastOptions::Strict)
                    .ok()?,
                _ => return None,
            };
            (scalar.dtype() == dtype).then(|| Column::new_scalar(name.clone(), scalar, 1))
        })
        .collect::<Option<Vec<_>>>()?;
    Some(IR::DataFrameScan {
        df: Arc::new(DataFrame::new(1, columns).ok()?),
        schema: schema.clone(),
        output_schema: None,
    })
}

